271|  try {
272|    validatedUrl = await validateUrl(urlInput);
273|  } catch (error) {
274|    const message = error instanceof Error ? error.message : String(error);
275|    return { ok: false, summary: message, error: 'url_blocked' };
276|  }
277|
278|  try {
279|    const response = await fetchImpl(validatedUrl.toString(), {
280|      method: 'GET',
