286|    });
287|
288|    if (!response.ok) {
289|      return {
290|        ok: false,
291|        summary: `Fetch failed (HTTP ${response.status}).`,
292|        error: 'fetch_failed',
293|      };
294|    }
295|
296|    const contentType = response.headers.get('content-type') ?? 'unknown';
297|    const rawBody = await response.text();
