306|      data: {
307|        url: validatedUrl.toString(),
308|        status: response.status,
309|        contentType,
310|        format,
311|        truncated,
312|        body: text,
313|      },
314|    };
315|  } catch (error) {
316|    const message = error instanceof Error ? error.message : String(error);
317|    return {
318|      ok: false,
319|      summary: `Fetch failed: ${message}`,
320|      error: 'fetch_failed',
